/// `word` may be a citation: the lemma, then any of `future.ind.act.1.sg`, `aorist.ind.act.1.sg`, `perfect.ind.act.1.sg`, `perfect.ind.mid.1.sg`, `aorist.ind.pass.1.sg` separated by commas.
/// Given parts are output exactly; the rest is predicted to agree with them.
pub fn present(word: &str, cell: PresentCell) -> Option<String> {
    AncientGreek::new().present(word, cell)
}

/// Every candidate for [`present`], most likely first. Confidences sum to the
/// probability that the word has such a form at all.
pub fn present_scored(word: &str, cell: PresentCell) -> Vec<Candidate> {
    AncientGreek::new().present_scored(word, cell)
}

